// ═══════════════════════════════════════════════════════════════
// WEEKLY REPORT CODE NODE
// Captures: last 7 days from today back to 7 days ago (inclusive)
// Today: May 6 → window = Apr 29 00:00  to  May 6 23:59
// ═══════════════════════════════════════════════════════════════

const allRows  = $input.all().map(i => i.json);

const allLeads = allRows.filter(r => r._sheet === 'leads');
const allChats = allRows.filter(r => r._sheet === 'chats');
const allAppts = allRows.filter(r => r._sheet === 'appts');
const allReeng = allRows.filter(r => r._sheet === 'reeng');
const allCalls = allRows.filter(r => r._sheet === 'calls');
const allContent = allRows.filter(r => (r._sheet === "content"));
// ── Date window (all LOCAL time — no UTC suffix) ─────────────────
const now = new Date();

const weekEnd = new Date(now);
weekEnd.setHours(23, 59, 59, 999);           // end of today

const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 6);        // 6 days back = 7 day window inclusive
weekStart.setHours(0, 0, 0, 0);             // start of that day

// ── Parsers (all return LOCAL Date objects, no UTC drift) ─────────

// Lead data: DD/MM/YYYY  e.g. "01/05/2026" = 1st May
function parseLeadDate(val) {
  if (!val) return null;
  val = String(val).trim();
  const parts = val.split('/');
  if (parts.length !== 3) return null;
  const dd = parseInt(parts[0]);
  const mm = parseInt(parts[1]) - 1;   // JS months are 0-indexed
  const yyyy = parseInt(parts[2]);
  if (yyyy < 1900 || yyyy > 2200) return null;
  const d = new Date(yyyy, mm, dd, 12, 0, 0); // noon local — avoids all DST edge cases
  return isNaN(d.getTime()) ? null : d;
}

// Content data parsing
// ── Parsers ─────────────────────────────────────────

// Content parser (ADD HERE)
function parseContentDate(val) {
  if (!val) return null;

  val = String(val).trim();
  const parts = val.split('/');

  if (parts.length !== 3) return null;

  let month = parseInt(parts[0]);
  let day = parseInt(parts[1]);
  let year = parseInt(parts[2]);

  // Fix wrong year like 0226 → 2026
  if (year < 2000) {
    year = 2000 + (year % 100);
  }

  const d = new Date(year, month - 1, day, 12, 0, 0);
  return isNaN(d.getTime()) ? null : d;
}
allContent.forEach((r, i) => {
  const d = parseContentDate(r.Timestamp);
  console.log(`Content[${i}] raw="${r.Timestamp}" → parsed="${d ? d.toDateString() : 'NULL'}" inWeek=${inWeek(d)}`);
});
const weeklyContent = allContent.filter(r => 
  inWeek(parseContentDate(r.Timestamp))
);

// Voiceflow: ISO 8601  e.g. "2026-05-06T11:47:03.321Z"
function parseISODate(val) {
  if (!val) return null;
  const d = new Date(String(val).trim());
  return isNaN(d.getTime()) ? null : d;
}

// Appointments: mixed — ISO rows AND "28/4/2026, 4:25:48 pm" rows
function parseApptDate(val) {
  if (!val) return null;
  val = String(val).trim();
  if (val.includes('T')) return parseISODate(val);
  if (val.includes(',')) return parseDDMMTime(val);
  return null;
}

// Re-engagement + Voice calls: "17/4/2026, 3:44:22 pm"  day first
function parseDDMMTime(val) {
  if (!val) return null;
  val = String(val).trim();
  if (!val.includes(',')) return null;
  const [datePart, timePart] = val.split(',');
  const seg = datePart.trim().split('/');
  if (seg.length !== 3) return null;
  const dd = parseInt(seg[0]);
  const mm = parseInt(seg[1]) - 1;
  const yyyy = parseInt(seg[2]);
  if (yyyy < 1900 || yyyy > 2200) return null;
  // Parse time portion "3:44:22 pm"
  const t = timePart.trim().toLowerCase();
  const timeMatch = t.match(/(\d+):(\d+):(\d+)\s*(am|pm)/);
  let hours = 0, minutes = 0, seconds = 0;
  if (timeMatch) {
    hours   = parseInt(timeMatch[1]);
    minutes = parseInt(timeMatch[2]);
    seconds = parseInt(timeMatch[3]);
    if (timeMatch[4] === 'pm' && hours < 12) hours += 12;
    if (timeMatch[4] === 'am' && hours === 12) hours = 0;
  }
  const d = new Date(yyyy, mm, dd, hours, minutes, seconds);
  return isNaN(d.getTime()) ? null : d;
}

// ── In-window checker ─────────────────────────────────────────────
function inWeek(d) {
  return d !== null && d >= weekStart && d <= weekEnd;
}

// ── Filter each sheet ─────────────────────────────────────────────
const weeklyLeads = allLeads.filter(r => inWeek(parseLeadDate(r.Timestamp)));
const weeklyChats = allChats.filter(r => inWeek(parseISODate(r.created_At)));
const weeklyAppts = allAppts.filter(r => inWeek(parseApptDate(r.Timestamp)));
const weeklyReeng = allReeng.filter(r => inWeek(parseDDMMTime(r.Call_time)));
const weeklyCalls = allCalls.filter(r => inWeek(parseDDMMTime(r.Timestamp)));

// ── Debug: prints in n8n Console tab ─────────────────────────────
console.log(`Weekly window: ${weekStart.toLocaleString()} → ${weekEnd.toLocaleString()}`);
console.log(`Leads total: ${allLeads.length} | in week: ${weeklyLeads.length}`);
console.log(`Chats total: ${allChats.length} | in week: ${weeklyChats.length}`);
console.log(`Appts total: ${allAppts.length} | in week: ${weeklyAppts.length}`);
console.log(`Reeng total: ${allReeng.length} | in week: ${weeklyReeng.length}`);
console.log(`Calls total: ${allCalls.length} | in week: ${weeklyCalls.length}`);

// Trace every lead row so you can see exactly what was parsed
allLeads.forEach((r, i) => {
  const d = parseLeadDate(r.Timestamp);
  console.log(`Lead[${i}] raw="${r.Timestamp}" → parsed="${d ? d.toLocaleDateString() : 'NULL'}" inWeek=${inWeek(d)}`);
});

// ── Metrics ───────────────────────────────────────────────────────
const totalCallCost = weeklyCalls
  .reduce((s, r) => s + Number(r.Call_cost || 0), 0).toFixed(2);

const avgResolution = weeklyChats.length
  ? (weeklyChats.reduce((s, r) => s + Number(r.resolution_rate || 0), 0)
     / weeklyChats.length * 100).toFixed(1)
  : '0';

const confirmedAppts = weeklyAppts
  .filter(r => r.Appintment_status === 'Confirmed').length;

const hotLeads = weeklyLeads
  .filter(r => r.Lead_type === 'Hot').length;

const reengInterested = weeklyReeng
  .filter(r => r.Intent === 'Interested').length;

const successCalls = weeklyCalls
  .filter(r => r.Call_outcome === 'Successful' || r.Call_status === 'completed').length;

const fullyPublished = weeklyContent.filter(r =>
  r.Blog_Status === 'Posted' &&
  r.Facebook_status === 'Posted' &&
  r.LinkedIn_status === 'Posted'
).length;

const pendingContent = weeklyContent.filter(r =>
  r.Blog_Status !== 'Posted'
).length;

// ── Output ────────────────────────────────────────────────────────
return [{
  json: {
    reportType:    'Weekly',
    period:        `${weekStart.toDateString()} – ${weekEnd.toDateString()}`,

    totalLeads:    weeklyLeads.length,
    hotLeads,

    totalChats:    weeklyChats.length,
    avgResolution,

    confirmedAppts,
    totalAppts:    weeklyAppts.length,

    totalCalls:    weeklyCalls.length,
    successCalls,
    totalCallCost,

    reengContacted: weeklyReeng.length,
    reengInterested,

    // Raw arrays for the email node if needed
    weeklyLeads,
    weeklyChats,
    weeklyAppts,
    weeklyReeng,
    weeklyCalls,

    totalContent: weeklyContent.length,
fullyPublished,
pendingContent,
weeklyContent
  }
}];

